const items=$input.all();
if(items.length!==1)throw new Error('Flow03 nhận 1 yêu cầu/lượt.');
const raw=items[0].json;
const webhookUrl=String(raw.webhookUrl||'');
const entrypoint=webhookUrl.includes('/flow03-auto')?'AUTO_WEBHOOK':webhookUrl?'MANUAL_WEBHOOK':'SUBWORKFLOW';
const input=raw.body ?? raw;
const env=typeof $env!=='undefined'?$env:{};
if(entrypoint==='AUTO_WEBHOOK'){
 const expected=String(env.INTERNAL_WEBHOOK_TOKEN||'').trim();
 const received=String(raw.headers?.['x-smart-classroom-internal']||'').trim();
 if(expected&&received!==expected)throw new Error('INTERNAL_WEBHOOK_UNAUTHORIZED');
}
if(entrypoint==='MANUAL_WEBHOOK'){
 const expected=String(env.N8N_MANUAL_TOKEN||'').trim();
 const auth=String(raw.headers?.authorization||'');
 const received=auth.startsWith('Bearer ')?auth.slice(7).trim():'';
 if(expected&&received!==expected)throw new Error('MANUAL_WEBHOOK_UNAUTHORIZED');
}
return [{json:{input,entrypoint,config:{
 backend_base_url:String(env.BACKEND_BASE_URL||'https://smart-classroom-backend-allm.onrender.com').replace(/\/+$/,''),
 dispatch_mode:String(env.FLOW03_DISPATCH_MODE||'FLOW04').toUpperCase(),
 flow04_webhook_url:String(env.N8N_PUBLIC_URL||env.WEBHOOK_URL||'').replace(/\/+$/,'')+'/webhook/flow04-dispatch'
}}}];

const c = $input.first().json;
const b = c.input;

const fail = (reason) => [{
  json: {
    eligible: false,
    automation_status: 'REJECTED',
    reason,
    commands: [],
    workflow_version: 'V3'
  }
}];

const uuid =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;

const types = [
  'FAN',
  'LIGHT',
  'VENTILATION',
  'DEHUMIDIFIER'
];

if (!b || typeof b !== 'object' || Array.isArray(b)) {
  return fail('Payload phải là object.');
}

if (
  typeof b.device_id !== 'string' ||
  !b.device_id.trim() ||
  b.device_id.length > 100
) {
  return fail('device_id không hợp lệ.');
}

if (!['BACKEND', 'FLOW04'].includes(c.config?.dispatch_mode)) {
  throw new Error('dispatch_mode không hợp lệ.');
}

if (
  c.config.dispatch_mode === 'FLOW04' &&
  !/^https?:\/\//.test(c.config.flow04_webhook_url || '')
) {
  throw new Error('Chưa cấu hình flow04_webhook_url.');
}

let request;

if (b.source === 'AUTO') {
  if (c.entrypoint === 'MANUAL_WEBHOOK') {
    return fail('Webhook manual không nhận AUTO.');
  }

  if (
    b.ready_for_commands !== true ||
    b.decision_status !== 'SAVED'
  ) {
    return fail('Decision chưa sẵn sàng.');
  }

  if (
    !uuid.test(b.decision_id || '') ||
    !uuid.test(b.telemetry_id || '')
  ) {
    return fail('Thiếu UUID decision/telemetry.');
  }

  const validUntil = Date.parse(b.valid_until);

  if (
    !Number.isFinite(validUntil) ||
    validUntil <= Date.now()
  ) {
    return fail('DECISION_EXPIRED');
  }

  if (!types.every(type =>
    ['ON', 'OFF'].includes(b.actions?.[type])
  )) {
    return fail('Thiếu actions hợp lệ.');
  }

  if (b.level != null) {
    return fail('AUTO chưa hỗ trợ level trong hợp đồng quyết định hiện tại.');
  }

  request = {
    device_id: b.device_id,
    source: 'AUTO',
    decision_id: b.decision_id
  };

} else if (b.source === 'MANUAL') {
  if (c.entrypoint === 'AUTO_WEBHOOK') return fail('Webhook AUTO không nhận MANUAL.');
  if (!uuid.test(b.request_id || '')) {
    return fail(
      'MANUAL cần request_id UUID ổn định khi retry. Backend /commands/manual tự tạo ID.'
    );
  }

  if (
    !types.includes(b.command_type) ||
    !['ON', 'OFF'].includes(b.action)
  ) {
    return fail('Lệnh thủ công không hợp lệ.');
  }

  if (
    !Number.isInteger(b.override_minutes) ||
    b.override_minutes < 1 ||
    b.override_minutes > 120
  ) {
    return fail('override_minutes phải từ 1 đến 120.');
  }

  // Level chỉ hỗ trợ FAN (0..3) và LIGHT (0..100).
  // Kiểm tra != null để giữ được level = 0.
  if (b.level != null) {
    const maxLevel =
      b.command_type === 'FAN' ? 3 :
      b.command_type === 'LIGHT' ? 100 :
      null;

    if (maxLevel === null) {
      return fail('level chỉ hỗ trợ FAN và LIGHT.');
    }

    if (
      !Number.isInteger(b.level) ||
      b.level < 0 ||
      b.level > maxLevel
    ) {
      return fail(
        `level của ${b.command_type} phải là số nguyên từ 0 đến ${maxLevel}.`
      );
    }

    if (b.action === 'OFF' && b.level !== 0) {
      return fail('Lệnh OFF phải có level bằng 0.');
    }

    if (b.action === 'ON' && b.level === 0) {
      return fail('Lệnh ON phải có level lớn hơn 0.');
    }
  }

  request = {
    device_id: b.device_id,
    source: 'MANUAL',
    request_id: b.request_id,
    command_type: b.command_type,
    action: b.action,
    override_minutes: b.override_minutes,
    ...(b.level != null ? { level: b.level } : {})
  };

} else {
  return fail('source phải là AUTO hoặc MANUAL.');
}

return [{
  json: {
    ...c,
    eligible: true,
    request
  }
}];

const r=$input.first().json;
if(r.statusCode<200||r.statusCode>=300||!Array.isArray(r.body?.commands_to_dispatch))throw new Error('Backend automation trả sai hợp đồng');
return [{json:{...r.body,config:$('Validate Request').first().json.config,has_commands:r.body.commands_to_dispatch.length>0}}];

return $input.all().map((i,index)=>{
 const r=i.json;if(r.statusCode<200||r.statusCode>=300||!r.body?.command)throw new Error('Invalid dispatch response');
 const c=r.body.command;
 return {json:{workflow_version:'V3',command_id:c.command_id||c.id,device_id:c.device_id,command_type:c.command_type,action:c.action,status:c.status,dispatch_reason:r.body.reason,dispatched:r.body.dispatched,ack_confirmed:c.status==='ACK',next_step:'Simulator HTTP claim → ACK. QUEUED không có nghĩa thiết bị đã thực hiện.'},pairedItem:{item:index}};
});
